+a { color: inherit; text-decoration: none; }
+img { display: block; max-width: 100%; }
+::selection { background: var(--lime); color: var(--ink); }
+
+.app { display: flex; min-height: 100vh; }
+.sidebar { width: var(--side-w); flex: none; position: sticky; top: 0; height: 100vh; overflow-y: auto; background: var(--side); border-right: 1px solid var(--line); padding: 22px 16px 20px; display: flex; flex-direction: column; gap: 4px; z-index: 50; }
+.sidebar::-webkit-scrollbar { width: 8px; }
+.sidebar::-webkit-scrollbar-thumb { background: rgba(0,0,0,.12); border-radius: 8px; }
+.logo { display: flex; align-items: center; gap: 10px; padding: 4px 8px 20px; }
+.bolt { width: 30px; height: 30px; border-radius: 8px; background: var(--ink); color: var(--lime); display: grid; place-items: center; flex: none; }
+.bolt svg { width: 16px; height: 16px; }
+.logo b { font-weight: 750; font-size: 18px; letter-spacing: -.04em; }
+.logo span:last-child { font-style: italic; font-size: 18px; color: var(--ink-2); letter-spacing: -.02em; }
+.navi, .cat { display: flex; align-items: center; gap: 12px; border-radius: 11px; color: var(--ink-2); transition: background .18s, color .18s; user-select: none; }
+.navi { padding: 9px 12px; font-size: 14.5px; font-weight: 520; }
+.navi:hover, .cat:hover { background: rgba(18,18,16,.055); color: var(--ink); }
+.navi.active, .cat.active { background: rgba(18,18,16,.07); color: var(--ink); font-weight: 650; }
+.navi svg { width: 18px; height: 18px; flex: none; stroke-width: 1.7; }
+.new { margin-left: auto; font-family: var(--mono); font-size: 8px; letter-spacing: .08em; background: var(--lime); padding: 2px 6px; border-radius: 5px; font-weight: 700; }
+.side-label { font-family: var(--mono); font-size: 9.5px; letter-spacing: .13em; text-transform: uppercase; color: var(--ink-3); padding: 0 12px; margin: 20px 0 7px; }
+.cat { width: 100%; padding: 7px 12px; font-size: 14px; text-align: left; }
+.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ink); opacity: .55; flex: none; }
+.cat.active .dot { background: var(--lime); opacity: 1; box-shadow: 0 0 0 3px rgba(201,250,70,.3); }
+.side-foot { margin-top: auto; padding-top: 20px; }
+.promo-card { background: var(--lime); border-radius: 14px; padding: 15px 16px; position: relative; overflow: hidden; }
+.promo-card h4 { font-size: 14px; font-weight: 700; letter-spacing: -.02em; margin: 0 0 4px; max-width: 78%; line-height: 1.2; }
+.promo-card p { font-size: 11.5px; color: rgba(18,18,16,.7); margin: 0; }
+.promo-card svg { position: absolute; top: 13px; right: 13px; width: 26px; height: 26px; }
+.side-cta { display: flex; align-items: center; gap: 12px; margin-top: 14px; }
+.btn-ink { background: var(--ink); color: #fff; font-family: var(--mono); font-size: 11px; letter-spacing: .09em; text-transform: uppercase; padding: 11px 16px; border-radius: 10px; transition: .22s; flex: 1; text-align: center; }
+.btn-ink:hover { background: var(--lime); color: var(--ink); }
+.free-link { font-size: 12.5px; color: var(--ink-3); white-space: nowrap; }
+.side-legal { display: flex; align-items: center; gap: 8px; margin-top: 18px; padding: 0 4px; font-size: 11.5px; color: var(--ink-3); flex-wrap: wrap; }
+.stars { display: inline-flex; align-items: center; gap: 3px; color: var(--ink); margin-left: auto; }
+
+.main { min-width: 0; flex: 1; padding: 0 18px 120px; }
+.mtop { height: 60px; align-items: center; gap: 10px; display: none; }
+.burger { width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center; background: rgba(18,18,16,.06); }
+.topbar { position: sticky; top: 0; z-index: 30; padding: 18px 0 13px; background: linear-gradient(var(--bg) 72%, rgba(237,236,230,0)); }
+.filterbar { display: flex; align-items: center; justify-content: space-between; gap: 14px; }
+.ftabs, .fsort, .searchbar { display: flex; align-items: center; gap: 6px; padding: 6px; border: 1px solid var(--line); background: rgba(245,244,239,.68); backdrop-filter: blur(12px); border-radius: 16px; }
+.ftabs { overflow-x: auto; scrollbar-width: none; }
+.ftab, .sortbtn { white-space: nowrap; border-radius: 11px; color: var(--ink-2); transition: .18s; }
+.ftab { display: inline-flex; align-items: center; gap: 7px; padding: 9px 12px; font-size: 13.5px; font-weight: 600; }
+.ftab svg { width: 16px; height: 16px; stroke-width: 1.8; }
+.ftab.active, .sortbtn.active { background: var(--ink); color: #fff; }
+.sortbtn { padding: 9px 11px; font-family: var(--mono); font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; }
+.searchbar { margin-top: 10px; width: min(520px, 100%); max-height: 0; opacity: 0; overflow: hidden; padding-block: 0; transition: .24s var(--ease); }
+.searchbar.open { max-height: 60px; opacity: 1; padding: 8px 10px; }
+.searchbar input { width: 100%; border: 0; outline: 0; background: transparent; font-size: 14px; }
+.hero { display: flex; justify-content: space-between; gap: 24px; align-items: flex-end; padding: 20px 2px 22px; }
+.hero h1 { margin: 0; max-width: 760px; font-size: clamp(2.45rem, 6vw, 5.8rem); line-height: .9; letter-spacing: -.075em; font-weight: 780; }
+.hero h1 em { font-family: Georgia, serif; font-weight: 400; font-style: italic; letter-spacing: -.09em; }
+.hero p { margin: 0 0 8px; max-width: 300px; color: var(--ink-2); font-size: 14px; }
+.metrics { display: flex; gap: 14px; color: var(--ink-3); font-family: var(--mono); font-size: 10px; letter-spacing: .08em; text-transform: uppercase; }
+
+.masonry { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); grid-auto-flow: dense; gap: 14px; align-items: start; }
+.tile { position: relative; min-height: 180px; border-radius: 18px; overflow: hidden; background: #dddcd5; box-shadow: 0 1px 0 rgba(18,18,16,.08); aspect-ratio: var(--ar); animation: fadeUp .55s var(--ease) both; }
+.tile.tall { grid-row: span 2; }
+.tile.wide { grid-column: span 2; }
+.media, .media img { width: 100%; height: 100%; }
+.media img { object-fit: cover; transition: transform .45s var(--ease), filter .45s; }
+.tile:hover img { transform: scale(1.045); filter: saturate(1.05) contrast(1.02); }
+.fb { height: 100%; display: grid; place-items: center; background: var(--fb-bg, var(--ink)); color: var(--fb-fg, var(--lime)); }
+.fb-mark { font-size: 74px; font-weight: 800; letter-spacing: -.08em; }
+.ov { position: absolute; inset: 0; display: flex; flex-direction: column; justify-content: space-between; padding: 12px; color: #fff; background: linear-gradient(to bottom, rgba(0,0,0,.55), rgba(0,0,0,.05) 36%, rgba(0,0,0,.72)); opacity: 0; transition: opacity .2s; }
+.tile:hover .ov, .tile:focus-within .ov { opacity: 1; }
+.ov__top, .ov__row { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
+.model { display: inline-flex; align-items: center; gap: 6px; background: rgba(255,255,255,.18); backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,.22); padding: 7px 9px; border-radius: 999px; font-family: var(--mono); font-size: 9.5px; letter-spacing: .09em; text-transform: uppercase; }
+.bm { width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; color: #fff; background: rgba(255,255,255,.16); backdrop-filter: blur(10px); }
+.bm.on, .bm:hover { background: var(--lime); color: var(--ink); }
+.bm svg { width: 17px; height: 17px; }
+.ov h3 { margin: 0 0 9px; font-size: 1.15rem; line-height: 1.02; letter-spacing: -.035em; font-weight: 720; text-shadow: 0 1px 10px rgba(0,0,0,.32); }
+.price { font-family: var(--mono); font-weight: 750; font-size: 16px; }
+.price.free { color: var(--lime); }
+.add { display: inline-flex; align-items: center; gap: 6px; border-radius: 999px; background: var(--lime); color: var(--ink); font-family: var(--mono); font-size: 10px; letter-spacing: .08em; text-transform: uppercase; padding: 8px 10px; font-weight: 700; }
+.savedmark { position: absolute; top: 11px; right: 11px; z-index: 4; width: 28px; height: 28px; border-radius: 8px; background: var(--lime); color: var(--ink); display: grid; place-items: center; box-shadow: 0 3px 10px rgba(0,0,0,.22); }
+.savedmark svg { width: 14px; height: 14px; fill: var(--ink); }
+.tile:hover .savedmark { display: none; }
+.empty { grid-column: 1 / -1; padding: 90px 20px; text-align: center; color: var(--ink-2); }
+.empty .big { font-size: 1.4rem; font-weight: 650; color: var(--ink); margin-bottom: 8px; }
+@keyframes fadeUp { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
+
+.dock { position: fixed; bottom: 22px; left: calc(50% + var(--side-w) / 2); transform: translateX(-50%); z-index: 80; display: flex; gap: 5px; padding: 8px; background: rgba(248,247,243,.72); backdrop-filter: blur(18px) saturate(1.4); border: 1px solid var(--line); border-radius: 21px; box-shadow: 0 16px 44px rgba(18,18,16,.16); }
+.dock button, .dock a { position: relative; width: 44px; height: 44px; border-radius: 13px; display: grid; place-items: center; color: var(--ink-2); transition: .18s; }
+.dock button:hover, .dock a:hover, .dock .active { background: var(--ink); color: #fff; }
+.dock svg { width: 20px; height: 20px; stroke-width: 1.7; }
+.cbadge { position: absolute; top: 5px; right: 5px; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px; background: var(--lime); color: var(--ink); font-family: var(--mono); font-size: 9px; font-weight: 700; display: grid; place-items: center; }
+.toast { position: fixed; bottom: 90px; left: calc(50% + var(--side-w) / 2); transform: translate(-50%, 150%); background: var(--ink); color: #fff; font-family: var(--mono); font-size: 12px; letter-spacing: .04em; padding: 13px 20px; border-radius: 11px; z-index: 120; display: flex; align-items: center; gap: 10px; box-shadow: 0 12px 32px rgba(0,0,0,.3); transition: transform .45s var(--ease); }
+.toast.show { transform: translate(-50%, 0); }
+.toast .d { width: 7px; height: 7px; border-radius: 50%; background: var(--lime); }
+
+.detail-card, .checkout, .analytics { margin: 24px auto 120px; max-width: 1080px; background: var(--card); border-radius: 22px; overflow: hidden; box-shadow: 0 20px 60px rgba(18,18,16,.12); }
+.detail-card { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(320px, .9fr); }
+.detail-media img { width: 100%; height: 100%; object-fit: cover; min-height: 560px; }
+.detail-info, .checkout, .analytics { padding: 32px; }
+.detail-info h1, .checkout h1, .analytics h1 { font-size: clamp(2rem, 4vw, 3.4rem); line-height: .98; letter-spacing: -.055em; margin: 12px 0 18px; }
+.desc { color: var(--ink-2); font-size: 17px; line-height: 1.58; }
+.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin: 28px 0; }
+.stat { border-top: 1px solid var(--line); padding-top: 12px; }
+.k { font-family: var(--mono); font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--ink-3); }
+.v { font-size: 20px; font-weight: 720; letter-spacing: -.02em; }
+.buy-row { display: flex; align-items: center; gap: 12px; padding-top: 22px; border-top: 1px solid var(--line); }
+.buy-row .price { font-size: 30px; }
+.buy-row .add { margin-left: auto; background: var(--ink); color: #fff; padding: 14px 20px; border-radius: 11px; }
+.list { display: grid; gap: 12px; }
+.line-item { display: grid; grid-template-columns: 74px 1fr auto; gap: 14px; align-items: center; padding: 12px 0; border-bottom: 1px solid var(--line); }
+.line-item img { width: 74px; height: 74px; border-radius: 14px; object-fit: cover; }
+.total-row { display: flex; justify-content: space-between; padding: 8px 0; color: var(--ink-2); }
+.total-row.final { color: var(--ink); font-weight: 760; font-size: 22px; border-top: 1px solid var(--line); margin-top: 10px; padding-top: 16px; }
+.grid-2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px; }
+.panel { border: 1px solid var(--line); border-radius: 18px; padding: 18px; }
+.panel ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
+.panel li { display: flex; justify-content: space-between; gap: 12px; border-bottom: 1px solid var(--line-2); padding-bottom: 8px; }
+
+.scrim { position: fixed; inset: 0; background: rgba(0,0,0,.45); z-index: 45; display: none; }
+.scrim.show { display: block; }
+
+@media (max-width: 960px) {
+  :root { --side-w: 0px; }
+  .sidebar { position: fixed; left: 0; transform: translateX(-100%); transition: transform .3s var(--ease); box-shadow: 0 0 50px rgba(0,0,0,.25); }
+  .sidebar.open { transform: none; }
+  .mtop { display: flex; }
+  .dock, .toast { left: 50%; }
+  .hero { display: block; }
+  .hero p { margin-top: 16px; }
+  .detail-card { grid-template-columns: 1fr; }
+  .detail-media img { min-height: auto; aspect-ratio: 16 / 10; }
+}
+
+@media (max-width: 620px) {
+  .main { padding-inline: 12px; }
+  .filterbar { flex-wrap: wrap; }
+  .fsort { width: 100%; justify-content: space-between; }
+  .hero h1 { font-size: 3.25rem; }
+  .masonry { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
+  .tile.wide { grid-column: span 2; }
+  .ov { opacity: 1; padding: 9px; }
+  .model { font-size: 8px; padding: 6px 7px; }
+  .ov h3 { font-size: .98rem; }
+  .bm { width: 32px; height: 32px; }
+  .stats, .grid-2 { grid-template-columns: 1fr; }
+  .detail-info, .checkout, .analytics { padding: 22px; }
+  .dock { bottom: 12px; }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  * { animation: none !important; transition: none !important; }
+}
*** End Patch

